mapper.select:
SELECT c.id, c.manu_id, m.company_name AS manu_name, c.service_id, sp.company_name AS service_name, c.demand_id, d.title AS demand_title, c.start_date, c.end_date, c.amount, c.status, c.create_time, (SELECT COUNT(*) > 0 FROM evaluation e WHERE e.coop_id = c.id AND e.evaluator_role = #{role} AND e.deleted = '1970-01-01 00:00:00' ) AS has_evaluated FROM cooperation c LEFT JOIN manufacture m ON c.manu_id = m.id AND m.deleted = '1970-01-01 00:00:00' LEFT JOIN service_provider sp ON c.service_id = sp.id AND sp.deleted = '1970-01-01 00:00:00' LEFT JOIN demand d ON c.demand_id = d.id AND d.deleted = '1970-01-01 00:00:00'
c.deleted = '1970-01-01 00:00:00'
AND c.manu_id = #{companyId}
AND c.service_id = #{companyId}
AND c.status = #{status}
ORDER BY c.create_time DESC
